func (this *Derive) fetchMarketsBody(ch chan AsyncResult[[]MarketInterface], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if *this.SafeBool(this.Options, "adjustForTimeDifference", false) {

		r := <-this.LoadTimeDifferenceAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	spotMarketsPromise := this.FetchSpotMarketsAsync(params)
	swapMarketsPromise := this.FetchSwapMarketsAsync(params)
	optionMarketsPromise := this.FetchOptionMarketsAsync(params)
	r1 := <-PromiseAllTyped[[]MarketInterface, AsyncResult[[]MarketInterface]](spotMarketsPromise, swapMarketsPromise, optionMarketsPromise)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var spotMarketsswapMarketsoptionMarketsVariable [][]any = StructListsToLists(r1.Value, MarketInterfaceToMap)
	var spotMarkets any = nil
	if spotMarketsswapMarketsoptionMarketsVariable[0] != nil {
		spotMarkets = spotMarketsswapMarketsoptionMarketsVariable[0]
	}
	var swapMarkets any = nil
	if spotMarketsswapMarketsoptionMarketsVariable[1] != nil {
		swapMarkets = spotMarketsswapMarketsoptionMarketsVariable[1]
	}
	var optionMarkets any = nil
	if spotMarketsswapMarketsoptionMarketsVariable[2] != nil {
		optionMarkets = spotMarketsswapMarketsoptionMarketsVariable[2]
	}
	//
	//     {
	//         "id": "dd959aa7-d878-45b8-926d-3a247376de90",
	//         "result": {
	//             "instruments": [
	//                 {
	//                     "instrument_type": "perp",
	//                     "instrument_name": "ZEC-PERP",
	//                     "scheduled_activation": 1780572941,
	//                     "scheduled_deactivation": 9223372036854775807,
	//                     "is_active": true,
	//                     "tick_size": "0.01",
	//                     "minimum_amount": "1",
	//                     "maximum_amount": "100000",
	//                     "amount_step": "0.01",
	//                     "mark_price_fee_rate_cap": "0",
	//                     "maker_fee_rate": "0.0001",
	//                     "taker_fee_rate": "0.0003",
	//                     "base_fee": "0.01",
	//                     "base_currency": "ZEC",
	//                     "quote_currency": "USDC",
	//                     "option_details": null,
	//                     "perp_details": {
	//                         "index": "ZEC-USD",
	//                         "max_rate_per_hour": "0.000456621005",
	//                         "min_rate_per_hour": "-0.000456621005",
	//                         "aggregate_funding": "26.08805211207",
	//                         "funding_rate": "0",
	//                         "srm_perp_margin_requirements": {
	//                             "im_perp_req": "0.15",
	//                             "mm_perp_req": "0.1",
	//                             "max_leverage": "6.67"
	//                         }
	//                     },
	//                     "erc20_details": null,
	//                     "base_asset_address": "0x7bF0D72275246A434151693c0EBBD38937dFE23b",
	//                     "base_asset_sub_id": "0",
	//                     "pro_rata_fraction": "0",
	//                     "fifo_min_allocation": "0",
	//                     "pro_rata_amount_step": "1"
	//                 }
	//             ],
	//             "pagination": {
	//                 "num_pages": 15,
	//                 "count": 15
	//             }
	//         }
	//     }
	//
	var result []any = this.ArrayConcat(spotMarkets, swapMarkets)
	result = this.ArrayConcat(result, optionMarkets)

	ch <- AsyncResult[[]MarketInterface]{Value: MarketInterfacesFromList(result)}
	return nil
}
