	//
	//     [
	//         {
	//             "trade_id": "28bea459-a2ff-45cc-a7e9-3d25448c859a",
	//             "instrument_name": "BTC-PERP",
	//             "timestamp": 1790792657383,
	//             "trade_price": "83863",
	//             "trade_amount": "0.0357",
	//             "mark_price": "83851.150918173763",
	//             "index_price": "83867.1716490259",
