	//             "trade_id": "b9608468-9ebe-478c-aedf-38fa2f754f19",
	//             "rfq_id": null,
	//             "timestamp": 1790874586675,
	//             "mark_price": "84367.247384690156",
	//             "index_price": "84358.49561857211",
	//             "trade_price": "84365.4",
	//             "trade_amount": "0.01",
