func (this *Derive) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	if price == nil {
		panic(ArgumentsRequired(this.Id + " createOrder() requires a price argument"))
	}
	subaccountIdparamsDeriveSubaccountIdVariable := this.HandleDeriveSubaccountId("createOrder", params)
	subaccountId := subaccountIdparamsDeriveSubaccountIdVariable[0]
	var paramsDeriveSubaccountId map[string]any = subaccountIdparamsDeriveSubaccountIdVariable[1].(map[string]any)
	var test *bool = this.SafeBool(paramsDeriveSubaccountId, "test", false)
	var reduceOnly *bool = this.SafeBool2(paramsDeriveSubaccountId, "reduceOnly", "reduce_only")
	var timeInForce *string = this.SafeStringLower2(paramsDeriveSubaccountId, "timeInForce", "time_in_force")
	var postOnly *bool = this.SafeBool(paramsDeriveSubaccountId, "postOnly")
	var orderType string = strings.ToLower(typeVar)
	var orderSide string = strings.ToLower(side)
	var orderSideIsBuy bool = (orderSide == "buy") // extracted to a named local: the Rust transpiler can't lower a bare `===` bool inside a list literal (ethAbiEncode args)
	var nonce string = this.NonceString()
	// Order signature expiry must be between 2592000 and 7776000 sec from now
	var signatureExpiry *int64 = this.SafeInteger(paramsDeriveSubaccountId, "signature_expiry_sec", this.Seconds()+7776000)
	var ACTION_TYPEHASH []byte = this.Base16ToBinary("4d7a9f27c403ff9c0f19bce61d76d82f9aa29f8d6d4b0c5474607d9770d1af17")
	var TRADE_MODULE_ADDRESS string = "0xB8D20c2B7a1Ad2EE33Bc50eF10876eD3035b5e7b" // shared across mainnet and testnet in v3
	var priceString *string = this.NumberToString(price)
	var maxFeeOptionAndParams []any = this.HandleOptionAndParams(paramsDeriveSubaccountId, "createOrder", "max_fee")
	var maxFeeString *string = this.SafeString(maxFeeOptionAndParams, 0)
	if maxFeeString == nil {
		panic(ArgumentsRequired(this.Id + " createOrder() requires a max_fee argument in params"))
	}
	var paramsMaxFee map[string]any = this.SafeDictMap(maxFeeOptionAndParams, 1, map[string]any{})
	var amountString *string = this.NumberToString(amount)
	var marketInfo map[string]any = SafeMapTyped(market, "info")
	var tradeModuleDataHash any = this.Hash(this.EthAbiEncode([]any{"address", "uint", "int", "int", "uint", "uint", "bool"}, []any{marketInfo["base_asset_address"], this.ConvertToBigInt(marketInfo["base_asset_sub_id"]), this.ConvertToBigInt(this.ParseUnits(priceString)), this.ConvertToBigInt(this.ParseUnits(this.AmountToPrecision(symbol, amountString))), this.ConvertToBigInt(this.ParseUnits(maxFeeString)), subaccountId, orderSideIsBuy}), keccak, "binary")
	deriveWalletAddressparamsDeriveWalletAddressVariable := this.HandleDeriveWalletAddress("createOrder", paramsMaxFee)
	var deriveWalletAddress *string = SafeStringPtr(deriveWalletAddressparamsDeriveWalletAddressVariable[0])
	var paramsDeriveWalletAddress map[string]any = deriveWalletAddressparamsDeriveWalletAddressVariable[1].(map[string]any)
	var signature string = this.SignOrder([]any{ACTION_TYPEHASH, subaccountId, this.ConvertToBigInt(nonce), TRADE_MODULE_ADDRESS, tradeModuleDataHash, signatureExpiry, deriveWalletAddress, this.WalletAddress}, this.PrivateKey)
	var request map[string]any = map[string]any{
		"instrument_name":      market["id"],
		"direction":            orderSide,
		"order_type":           orderType,
		"nonce":                nonce,
		"amount":               amountString,
		"limit_price":          priceString,
		"max_fee":              maxFeeString,
		"subaccount_id":        subaccountId,
		"signature_expiry_sec": signatureExpiry,
		"referral_code":        this.SafeString(this.Options, "id", "0x0ad42b8e602c2d3d475ae52d678cf63d84ab2749"),
		"signer":               this.WalletAddress,
	}
	if reduceOnly != nil {
		request["reduce_only"] = reduceOnly
		if (reduceOnly != nil && *reduceOnly) && (postOnly != nil && *postOnly == true) {
			panic(InvalidOrder(this.Id + " cannot use reduce only with post only time in force"))
		}
	}
	if postOnly != nil {
		request["time_in_force"] = "post_only"
	} else if timeInForce != nil {
		request["time_in_force"] = timeInForce
	}
	// the venue supports exactly two standalone conditional kinds: 'stoploss' triggers on adverse crossing (the classic stop semantics, so both triggerPrice and stopLossPrice map onto it) and 'takeprofit' triggers on the favorable one; attached stop loss / take profit are not supported
	var triggerPrice *string = this.SafeStringN(paramsDeriveWalletAddress, []any{"triggerPrice", "stopPrice", "trigger_price"})
	var stopLossPrice *string = this.SafeString(paramsDeriveWalletAddress, "stopLossPrice")
	var takeProfitPrice *string = this.SafeString(paramsDeriveWalletAddress, "takeProfitPrice")
	if (takeProfitPrice != nil) && ((triggerPrice != nil) || (stopLossPrice != nil)) {
		panic(InvalidOrder(this.Id + " createOrder() accepts only one of triggerPrice, stopLossPrice or takeProfitPrice"))
	}
	var triggerPriceType *string = this.SafeString(paramsDeriveWalletAddress, "trigger_price_type", "mark")
	var stopPrice *string = func() *string {
		if triggerPrice != nil {
			return triggerPrice
		}
		return stopLossPrice
	}()
	if stopPrice != nil {
		request["trigger_price"] = stopPrice
		request["trigger_type"] = "stoploss"
		request["trigger_price_type"] = triggerPriceType
	} else if takeProfitPrice != nil {
		request["trigger_price"] = takeProfitPrice
		request["trigger_type"] = "takeprofit"
		request["trigger_price_type"] = triggerPriceType
	}
	var clientOrderId *string = this.SafeString(paramsDeriveWalletAddress, "clientOrderId")
	if clientOrderId != nil {
		request["label"] = clientOrderId
	}
	request["signature"] = signature
	var paramsOmitted map[string]any = this.OmitDict(paramsDeriveWalletAddress, []any{"reduceOnly", "reduce_only", "timeInForce", "time_in_force", "postOnly", "test", "clientOrderId", "stopPrice", "triggerPrice", "trigger_price", "stopLossPrice", "takeProfitPrice", "trigger_price_type"})
	var response map[string]any = nil
	if test != nil && *test {

		r1 := <-this.PrivatePostOrderDebug(this.Extend(request, paramsOmitted))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	} else {

		r2 := <-this.PrivatePostOrder(this.Extend(request, paramsOmitted))
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Value
	}
	//
	//     {
	//         "id": "dd0fe5ec-043c-41ab-95e1-fc2421c6fc10",
	//         "result": {
	//             "order": {
	//                 "subaccount_id": 86815,
	//                 "order_id": "f690dfc9-5b9c-4f62-a2b0-3f6ba502f2f6",
	//                 "instrument_name": "BTC-PERP",
	//                 "direction": "buy",
	//                 "label": "",
	//                 "quote_id": null,
	//                 "amount": "0.01",
	//                 "average_price": "0",
	//                 "cancel_reason": "",
	//                 "creation_timestamp": 1790871618199,
	//                 "filled_amount": "0",
	//                 "is_transfer": false,
	//                 "last_update_timestamp": 1790871618199,
	//                 "limit_price": "83000",
	//                 "signed_limit_price": null,
	//                 "max_fee": "100",
	//                 "mmp": false,
	//                 "nonce": "1790871617137835612",
	//                 "order_fee": "0",
	//                 "order_status": "open",
	//                 "order_type": "limit",
	//                 "replaced_order_id": null,
	//                 "signature": "0x55412a2a39e2dd70b0c39ea03859ac499b5c500756b46197900a413f7bfd294e0adb8c2c5eec467b4c83ef75f7068b528e21044cdd27faa47a6db475461641c21b",
	//                 "signature_expiry_sec": 1798647617,
	//                 "signer": "0x9050dfA063D1bE7cA711c750b18D51fDD13e90Ee",
	//                 "time_in_force": "gtc",
	//                 "trigger_type": null,
	//                 "trigger_price": null,
	//                 "trigger_price_type": null,
	//                 "trigger_reject_message": null,
	//                 "extra_fee": "0",
	//                 "algo_type": null,
	//                 "algo_duration_sec": null,
	//                 "algo_num_slices": null,
	//                 "algo_slices_completed": null
	//             },
	//             "trades": []
	//         }
	//     }
	//
	var result map[string]any = SafeMapTyped(response, "result")
	var rawOrder any = this.SafeDict(result, "raw_data")
	if rawOrder == nil {
		rawOrder = this.SafeDict(result, "order", map[string]any{})
	}
	var order map[string]any = OrderToMap(this.ParseOrder(rawOrder, market))
	order["type"] = typeVar

	ch <- AsyncResult[Order]{Value: OrderFromMap(order)}
	return nil
}

